// Des: List likely JSON or page URLs behind JS shells
// Flo: link tags > wp-json > Next buildId > Nuxt payload > SvelteKit data > /api/ strings > openapi > iframes > .json twin > same-host dedupe
// I/O: page URL + HTML text (caller) > Cand list (absolute same-host URLs, kind label, page flag)
// ===================================================================
const std = @import("std"); const mem2 = std.mem; const urln = @import("ut-urlz-norm.zig"); const stru = @import("pa-stru-data.zig");
const CF = .{ .maxc = 32, .scrn = 12, .ulen = 200, .jtyp = @as([]const []const u8, &.{ "application/json", "application/feed+json", "application/vnd.api+json" }) };
pub const Cand = struct { urlz: []const u8, kind: []const u8, page: bool = false };
fn attrGetz(tagz: []const u8, name: []const u8) ?[]const u8 { var buf4: [16]u8 = undefined; const patz = std.fmt.bufPrint(&buf4, "{s}=", .{name}) catch return null; var from: usize = 0; while (std.ascii.findIgnoreCasePos(tagz, from, patz)) |hitz| { from = hitz + patz.len; if (hitz == 0 or !std.ascii.isWhitespace(tagz[hitz - 1])) continue; if (from >= tagz.len) return null; const quot = tagz[from]; if (quot != '"' and quot != '\'') return null; const endz = mem2.findScalarPos(u8, tagz, from + 1, quot) orelse return null; return tagz[from + 1 .. endz]; } return null; }
pub fn ori2(aren: std.mem.Allocator, part: urln.Part) ![]const u8 { if (part.dflt) return std.fmt.allocPrint(aren, "{s}://{s}", .{ part.sche, part.host }); return std.fmt.allocPrint(aren, "{s}://{s}:{d}", .{ part.sche, part.host, part.port }); }
pub fn joi2(aren: std.mem.Allocator, part: urln.Part, orig: []const u8, refz: []const u8) !?[]const u8 { const ref2 = mem2.trim(u8, refz, " \t\r\n"); if (ref2.len == 0 or ref2.len > CF.ulen or ref2[0] == '#') return null; if (std.ascii.startsWithIgnoreCase(ref2, "http://") or std.ascii.startsWithIgnoreCase(ref2, "https://")) return try aren.dupe(u8, ref2); if (std.ascii.startsWithIgnoreCase(ref2, "javascript:") or std.ascii.startsWithIgnoreCase(ref2, "data:")) return null; if (mem2.startsWith(u8, ref2, "//")) return try std.fmt.allocPrint(aren, "{s}:{s}", .{ part.sche, ref2 }); if (ref2[0] == '/') return try std.fmt.allocPrint(aren, "{s}{s}", .{ orig, ref2 }); const dirx = if (mem2.findScalarLast(u8, part.path, '/')) |slzz| part.path[0 .. slzz + 1] else "/"; return try std.fmt.allocPrint(aren, "{s}{s}{s}", .{ orig, dirx, ref2 }); }
fn sameHost(part: urln.Part, urlz: []const u8) bool { const othe = urln.urlzSpli(urlz) catch return false; return std.ascii.eqlIgnoreCase(othe.host, part.host) and othe.port == part.port; }
const Bild = struct { aren: std.mem.Allocator, part: urln.Part, orig: []const u8, list: std.ArrayList(Cand) = .empty,
fn add2(self: *Bild, refz: []const u8, kind: []const u8, page: bool) !void { if (self.list.items.len >= CF.maxc) return; const urlz = (try joi2(self.aren, self.part, self.orig, refz)) orelse return; if (!sameHost(self.part, urlz)) return; for (self.list.items) |item| if (mem2.eql(u8, item.urlz, urlz)) return; try self.list.append(self.aren, .{ .urlz = urlz, .kind = kind, .page = page }); } };
fn pathTrim(part: urln.Part) []const u8 { return mem2.trimEnd(u8, part.path, "/"); }
fn tagsOfzz(bldz: *Bild, page: []const u8, open: []const u8) !void { var indx: usize = 0; var con2: usize = 0; while (std.ascii.findIgnoreCasePos(page, indx, open)) |begz| { const endz = mem2.findScalarPos(u8, page, begz, '>') orelse break; indx = endz + 1; con2 += 1; if (con2 > 64) break; const tagz = page[begz..endz]; if (std.ascii.eqlIgnoreCase(open, "<iframe")) { if (attrGetz(tagz, "src")) |srcz| try bldz.add2(srcz, "ifrm", true); continue; } const href = attrGetz(tagz, "href") orelse continue; const relz = attrGetz(tagz, "rel") orelse ""; if (std.ascii.findIgnoreCase(relz, "api.w.org") != null) { const root = if (mem2.endsWith(u8, href, "/")) href else try std.fmt.allocPrint(bldz.aren, "{s}/", .{href}); try bldz.add2(try std.fmt.allocPrint(bldz.aren, "{s}wp/v2/posts?per_page=10", .{root}), "wpjs", false); try bldz.add2(try std.fmt.allocPrint(bldz.aren, "{s}wp/v2/pages?per_page=10", .{root}), "wpjs", false); continue; } if (std.ascii.findIgnoreCase(relz, "alternate") == null) continue; const typz = attrGetz(tagz, "type") orelse continue; for (CF.jtyp) |jtzz| if (std.ascii.findIgnoreCase(typz, jtzz) != null) { try bldz.add2(href, "link", false); break; }; } }
fn nextBild(bldz: *Bild, page: []const u8) !void { const blks = try stru.blokFind(bldz.aren, page); for (blks) |blkz| { if (blkz.kind != .next) continue; const valu = std.json.parseFromSliceLeaky(std.json.Value, bldz.aren, blkz.json, .{}) catch continue; if (valu != .object) continue; const bidz = valu.object.get("buildId") orelse continue; if (bidz != .string or bidz.string.len == 0 or bidz.string.len > 64) continue; const tail = mem2.trim(u8, bldz.part.path, "/"); try bldz.add2(try std.fmt.allocPrint(bldz.aren, "/_next/data/{s}/{s}.json", .{ bidz.string, if (tail.len == 0) "index" else tail }), "next", false); return; } }
fn scrzStrs(bldz: *Bild, page: []const u8) !void { var con2: usize = 0; for ([_][]const u8{ "/api/", "/wp-json/" }) |patz| { var indx: usize = 0; while (mem2.findPos(u8, page, indx, patz)) |hitz| { indx = hitz + patz.len; if (hitz == 0 or (page[hitz - 1] != '"' and page[hitz - 1] != '\'')) continue; var endz = hitz; while (endz < page.len and endz - hitz < CF.ulen and page[endz] != '"' and page[endz] != '\'' and page[endz] != '<' and page[endz] != '`' and !std.ascii.isWhitespace(page[endz])) : (endz += 1) {} const cand = page[hitz..endz]; if (mem2.findAny(u8, cand, "{}$\\") != null or endz >= page.len) continue; try bldz.add2(cand, "scri", false); con2 += 1; if (con2 >= CF.scrn) return; } } }
pub fn apizFind(aren: std.mem.Allocator, norm: []const u8, page: []const u8, extr: []const []const u8) ![]Cand { const part = try urln.urlzSpli(norm); var bldz: Bild = .{ .aren = aren, .part = part, .orig = try ori2(aren, part) }; try tagsOfzz(&bldz, page, "<link"); try nextBild(&bldz, page); if (std.ascii.findIgnoreCase(page, "__NUXT_DATA__") != null) try bldz.add2(try std.fmt.allocPrint(aren, "{s}/_payload.json", .{pathTrim(part)}), "nuxt", false); if (std.ascii.findIgnoreCase(page, "sveltekit") != null) try bldz.add2(try std.fmt.allocPrint(aren, "{s}/__data.json", .{pathTrim(part)}), "svel", false); try scrzStrs(&bldz, page); if (std.ascii.findIgnoreCase(page, "swagger") != null or std.ascii.findIgnoreCase(page, "openapi") != null) { try bldz.add2("/openapi.json", "oapi", false); try bldz.add2("/swagger.json", "oapi", false); } try tagsOfzz(&bldz, page, "<iframe"); const trim = pathTrim(part); if (trim.len > 0 and !mem2.endsWith(u8, trim, ".json")) try bldz.add2(try std.fmt.allocPrint(aren, "{s}.json", .{trim}), "twin", false); for (extr) |extz| try bldz.add2(extz, "cust", false); return bldz.list.toOwnedSlice(aren); }
